<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';
type Section={id:number;name:string;key:string;type:string;content:Record<string,unknown>;is_active:boolean};
const rows=ref<Section[]>([]),error=ref(''),open=ref(false),id=ref<number|null>(null),saving=ref(false);
const f=reactive({name:'',key:'',type:'rich_text',content:'{}',is_active:true});
const csrf=()=>document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';
async function api(url:string,method='GET',body?:unknown){const r=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf()},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Request failed');return d}
async function load(){try{rows.value=(await api('/api/v1/backend/cms/sections')).data??[]}catch(e){error.value=(e as Error).message}}
function reset(){Object.assign(f,{name:'',key:'',type:'rich_text',content:'{}',is_active:true});id.value=null;open.value=true}
function edit(s:Section){Object.assign(f,{name:s.name,key:s.key,type:s.type,content:JSON.stringify(s.content,null,2),is_active:s.is_active});id.value=s.id;open.value=true}
async function save(){saving.value=true;error.value='';try{const content=JSON.parse(f.content);if(!content||Array.isArray(content)||typeof content!=='object')throw Error('Content must be a JSON object.');const body={...f,content};await api(id.value?`/api/v1/backend/cms/sections/${id.value}`:'/api/v1/backend/cms/sections',id.value?'PUT':'POST',body);open.value=false;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function remove(s:Section){if(!confirm(`Delete reusable section "${s.name}"?`))return;try{await api(`/api/v1/backend/cms/sections/${s.id}`,'DELETE');await load()}catch(e){error.value=(e as Error).message}}
onMounted(load);</script>
<template><ErpLayout><div class="wrap"><header class="erp-page-header"><div class="erp-page-heading"><nav class="erp-page-breadcrumb" aria-label="Breadcrumb"><span>Workspace</span><span aria-hidden="true">›</span><span>Website Management</span><span aria-hidden="true">›</span><strong>Reusable Sections</strong></nav><div class="erp-page-title-line"><span class="erp-page-title-icon"><Icon name="layout-grid" :size="20" /></span><div><small>WEBSITE MANAGEMENT</small><h1>Reusable Content Sections</h1><p>Create structured content blocks that can be reused across website pages.</p></div></div></div><button class="primary" @click="reset">＋ Create section</button></header><p v-if="error" class="error">{{error}}</p><section class="list"><article v-for="s in rows" :key="s.id"><div><strong>{{s.name}}</strong><code>{{s.key}}</code><small>{{s.type}} · {{s.is_active?'Active':'Inactive'}}</small></div><div><button @click="edit(s)">Edit</button> <button class="danger" @click="remove(s)">Delete</button></div></article><p v-if="!rows.length" class="empty">No reusable sections yet.</p></section><div v-if="open" class="shade" @click.self="open=false"><form class="modal" @submit.prevent="save"><h2>{{id?'Edit':'Create'}} section</h2><label>Name<input v-model="f.name" required maxlength="180"></label><label>Unique key<input v-model="f.key" required pattern="[A-Za-z0-9_-]+" maxlength="190"></label><label>Section type<select v-model="f.type"><option value="rich_text">Rich text</option><option value="hero">Hero</option><option value="image_text">Image + text</option><option value="feature_grid">Feature grid</option><option value="cta">Call to action</option></select></label><label>Content JSON<textarea v-model="f.content" rows="10" spellcheck="false"></textarea></label><label class="check"><input v-model="f.is_active" type="checkbox"> Active</label><footer><button type="button" @click="open=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving…':'Save section'}}</button></footer></form></div></div></ErpLayout></template>
<style scoped>
.wrap{padding:0}header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}small{display:block;color:#64748b}h1{font-size:25px;margin:4px 0}p{color:#64748b}button{padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;background:white;cursor:pointer}.primary{background:#174c3c;color:white;border-color:#174c3c}.danger,.error{color:#b91c1c}.list{border:1px solid #e2e8f0;border-radius:12px;background:white}.list article{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px;border-bottom:1px solid #edf0f4}.list article:last-child{border:0}.list code{display:inline-block;margin-left:12px;background:#f1f5f9;padding:3px 6px;border-radius:5px}.empty{text-align:center;padding:30px}.shade{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;z-index:1000;padding:15px}.modal{background:white;border-radius:14px;padding:22px;width:min(620px,100%);max-height:90vh;overflow:auto;display:grid;gap:12px}.modal h2{margin:0}.modal label{display:grid;gap:5px;font-size:13px;font-weight:600}.modal input,.modal select,.modal textarea{padding:10px;border:1px solid #cbd5e1;border-radius:8px;min-width:0;font:inherit}.modal textarea{font-family:monospace}.modal .check{display:flex;align-items:center}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:8px}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}}
</style>
